func _shoot() -> void:
	var angles: Array = [0.0]
	if spread_time > 0.0:
		angles = [-0.2, 0.0, 0.2]
	for angle in angles:
		var bullet := BulletScript.new()
		bullet.position = position + Vector2(0, -30)
		bullet.velocity = Vector2.UP.rotated(angle) * BULLET_SPEED
		bullet.field = field
		bullet_parent.add_child(bullet)

func _drop_pickup(at: Vector2) -> void:
	var pickup := PickupScript.new()
	pickup.kind = "heart" if player.lives < PlayerScript.MAX_LIVES and randf() < 0.4 else "spread"
	pickup.field = FIELD
	pickup.position = at
	world.call_deferred("add_child", pickup)

func take_hit() -> void:
	if invulnerable > 0.0 or not alive:
		return
	lives -= 1
	Audio.play("player_hit")
	hit.emit(lives)
	if lives <= 0:
		alive = false
		visible = false
		set_deferred("monitoring", false)
		died.emit()
	else:
		invulnerable = INVULNERABLE_TIME

func _show_game_over() -> void:
	# MainChar: gameOverScreen.SetActive(true); Time.timeScale = 0
	if config.boss:
		game_over_score.text = "Score: %d\nThe Cerberus still guards the gate." % score
	else:
		game_over_score.text = "Score: %d     /%d" % [score, config.goal]
	game_over_menu.visible = true
	get_tree().paused = true
	game_over_menu.get_meta("buttons")[0].grab_focus()

if effects_parent:
	Effects.hit_spark(effects_parent, at)
if state == "enter":
	return true   # shielded while it walks in: the shot is absorbed
var was_enraged := enraged()
health = maxi(0, health - amount)
health_changed.emit(health, MAX_HEALTH)
Audio.play("enemy_hit", -3.0)
_flash()
if not was_enraged and enraged():
	sprite.modulate = Color(1.0, 0.7, 0.7)
