func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("pause"):
		if state == "over":
			return
		if pause_menu.visible:
			_resume()
		elif state == "play" or state == "intro":
			_pause()
		get_viewport().set_input_as_handled()
	elif event.is_action_pressed("restart") and (pause_menu.visible or game_over_menu.visible):
		_restart()
		get_viewport().set_input_as_handled()

func _process(delta: float) -> void:
	if finished or stop_y == 0.0:
		return
	credits.position.y -= SCROLL_SPEED * delta
	if credits.position.y <= stop_y:
		_finish()

func _finish() -> void:
	finished = true
	credits.position.y = stop_y
	buttons.visible = true
	create_tween().tween_property(buttons, "modulate:a", 1.0, 0.5)
	buttons.get_child(0).grab_focus()
